package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SamlIdpMetadataUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property saml idp metadata url of tenant login provider ")
  void test_saml_idp_metadata_url_v_o_builder() {
    Assertions.assertFalse(SamlIdpMetadataUrlVO.nullValue().getSamlIdpMetadataUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SamlIdpMetadataUrlVO.tryFrom(null).getSamlIdpMetadataUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        SamlIdpMetadataUrlVO.from("one").getSamlIdpMetadataUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SamlIdpMetadataUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SamlIdpMetadataUrlVO.from("one").toString());
  }
}
